                    transaction_id VARCHAR(100) NOT NULL,
                    paid_at TIMESTAMP NOT NULL,
                    PRIMARY KEY (order_id, transaction_id)
                )
            """);
        } catch (SQLException e) {
            throw new RuntimeException("Failed to initialize database schema", e);
        }
    }
}

