                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to create order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order getOrder(String orderId) {
        return orderRepository.findById(orderId)
            .orElseThrow(() -> new ApiException("ORDER_NOT_FOUND", 404));
    }

    public Order processPayment(String orderId, String transactionId, Instant paidAt) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
                if (existingOrder.isEmpty()) {
                    conn.rollback();
                    throw new ApiException("ORDER_NOT_FOUND", 404);
                }

                Order order = existingOrder.get();

                if (transactionId == null || transactionId.isEmpty() || paidAt == null) {
                    conn.rollback();
                    throw new ApiException("INVALID_ORDER", 422);
                }

                boolean isNewTransaction = orderRepository.recordPaymentTransaction(orderId, transactionId, paidAt, conn);

                if (!isNewTransaction) {
                    conn.rollback();
                    return order;
                }

                if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
                    conn.rollback();
                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
                }

                Duration elapsed = Duration.between(order.getCreatedAt(), paidAt);
                if (elapsed.compareTo(Duration.ofHours(48)) > 0) {
                    orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
                    order.setStatus(OrderStatus.CANCELLED);
                    notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
                    conn.commit();
                    throw new ApiException("ORDER_EXPIRED", 409);
                }

                Map<String, Integer> skuQuantities = new HashMap<>();
                for (OrderItem item : order.getItems()) {
                    skuQuantities.put(item.getSku(), item.getQuantity());
                }

                try {
                    productRepository.decreaseStock(skuQuantities, conn);
                } catch (SQLException e) {
                    if (e.getMessage().equals("INSUFFICIENT_STOCK")) {
                        orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
                        order.setStatus(OrderStatus.CANCELLED);
                        notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
                        conn.commit();
                        throw new ApiException("INSUFFICIENT_STOCK", 409);
                    }
                    throw e;
                }

                if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
                    customerRepository.addCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit(), conn);
                }

                orderRepository.updateStatus(orderId, OrderStatus.PAID, conn);
                orderRepository.updatePaymentTransaction(orderId, transactionId, conn);
                order.setStatus(OrderStatus.PAID);
                order.setPaymentTransactionId(transactionId);

                notificationRepository.create(order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId, conn);

                conn.commit();
                return order;
            } catch (ApiException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to process payment", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order shipOrder(String orderId, String trackingCode) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
                if (existingOrder.isEmpty()) {
                    conn.rollback();
                    throw new ApiException("ORDER_NOT_FOUND", 404);
                }

                Order order = existingOrder.get();

                if (trackingCode == null || trackingCode.isEmpty()) {
                    conn.rollback();
                    throw new ApiException("INVALID_ORDER", 422);
                }

                if (order.getStatus() != OrderStatus.PAID) {
                    conn.rollback();
                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
                }

                orderRepository.updateStatus(orderId, OrderStatus.SHIPPED, conn);
                orderRepository.updateTrackingCode(orderId, trackingCode, conn);
                order.setStatus(OrderStatus.SHIPPED);
                order.setTrackingCode(trackingCode);

                notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId, conn);

                conn.commit();
                return order;
            } catch (ApiException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to ship order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order deliverOrder(String orderId) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
                if (existingOrder.isEmpty()) {
                    conn.rollback();
                    throw new ApiException("ORDER_NOT_FOUND", 404);
                }

                Order order = existingOrder.get();

                if (order.getStatus() != OrderStatus.SHIPPED) {
                    conn.rollback();
                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
                }

                orderRepository.updateStatus(orderId, OrderStatus.DELIVERED, conn);
                order.setStatus(OrderStatus.DELIVERED);

                conn.commit();
                return order;
            } catch (ApiException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to deliver order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }

    public Order cancelOrder(String orderId) {
        try (Connection conn = database.getConnection()) {
            conn.setAutoCommit(false);
            try {
                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
                if (existingOrder.isEmpty()) {
                    conn.rollback();
                    throw new ApiException("ORDER_NOT_FOUND", 404);
                }

                Order order = existingOrder.get();

                if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
                    conn.rollback();
                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
                }

                if (order.getStatus() == OrderStatus.PAID) {
                    Map<String, Integer> skuQuantities = new HashMap<>();
                    for (OrderItem item : order.getItems()) {
                        skuQuantities.put(item.getSku(), item.getQuantity());
                    }
                    productRepository.increaseStock(skuQuantities, conn);

                    if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
                        customerRepository.subtractCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit(), conn);
                    }
                }

                orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
                order.setStatus(OrderStatus.CANCELLED);

                notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);

                conn.commit();
                return order;
            } catch (ApiException e) {
                conn.rollback();
                throw e;
            } catch (Exception e) {
                conn.rollback();
                throw new RuntimeException("Failed to cancel order", e);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Database connection failed", e);
        }
    }
}
package com.loja.repository;

import com.loja.domain.Product;

import java.sql.*;
import java.util.*;

public class ProductRepository {
    private final Database database;

    public ProductRepository(Database database) {
        this.database = database;
    }

    public void initializeCatalog() {
        try (Connection conn = database.getConnection()) {
            String checkSql = "SELECT COUNT(*) FROM products";
            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(checkSql)) {
                rs.next();
                if (rs.getInt(1) > 0) {
                    return;
                }
            }

            String insertSql = "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES (?, ?, ?, ?, ?, ?)";
            try (PreparedStatement pstmt = conn.prepareStatement(insertSql)) {
                Object[][] catalog = {
                    {"CAM-001", "Camiseta básica", 79.90, 0.30, 50, false},
                    {"TEN-001", "Tênis corrida", 249.90, 1.20, 10, false},
                    {"FON-001", "Fone sem fio", 199.90, 0.25, 5, false},
                    {"MEI-001", "Meia esportiva", 19.90, 0.10, 100, false},
                    {"JAQ-001", "Jaqueta corta-vento", 389.90, 0.80, 3, false},
                    {"MOC-001", "Mochila urbana", 159.90, 0.90, 1, false},
                    {"BON-001", "Boné aba reta", 59.90, 0.15, 0, false},
                    {"REL-001", "Relógio digital", 129.90, 0.20, 8, true}
                };

                for (Object[] item : catalog) {
                    pstmt.setString(1, (String) item[0]);
                    pstmt.setString(2, (String) item[1]);
                    pstmt.setBigDecimal(3, new java.math.BigDecimal(item[2].toString()));
                    pstmt.setBigDecimal(4, new java.math.BigDecimal(item[3].toString()));
                    pstmt.setInt(5, (Integer) item[4]);
                    pstmt.setBoolean(6, (Boolean) item[5]);
                    pstmt.addBatch();
                }
                pstmt.executeBatch();
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to initialize catalog", e);
        }
    }

    public Optional<Product> findBySku(String sku) {
        String sql = "SELECT * FROM products WHERE sku = ?";
        try (Connection conn = database.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, sku);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(mapProduct(rs));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to find product", e);
        }
        return Optional.empty();
    }

    public Map<String, Product> findBySkus(Collection<String> skus) {
        if (skus.isEmpty()) {
            return Collections.emptyMap();
        }

        String placeholders = String.join(",", Collections.nCopies(skus.size(), "?"));
        String sql = "SELECT * FROM products WHERE sku IN (" + placeholders + ")";

        Map<String, Product> products = new HashMap<>();
        try (Connection conn = database.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            int index = 1;
            for (String sku : skus) {
                pstmt.setString(index++, sku);
            }
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    Product product = mapProduct(rs);
                    products.put(product.getSku(), product);
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to find products", e);
        }
        return products;
    }

    public void decreaseStock(Map<String, Integer> skuQuantities, Connection conn) throws SQLException {
        String sql = "UPDATE products SET stock = stock - ? WHERE sku = ? AND stock >= ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            for (Map.Entry<String, Integer> entry : skuQuantities.entrySet()) {
                pstmt.setInt(1, entry.getValue());
                pstmt.setString(2, entry.getKey());
                pstmt.setInt(3, entry.getValue());
                int updated = pstmt.executeUpdate();
                if (updated == 0) {
                    throw new SQLException("INSUFFICIENT_STOCK");
                }
            }
        }
    }

    public void increaseStock(Map<String, Integer> skuQuantities, Connection conn) throws SQLException {
        String sql = "UPDATE products SET stock = stock + ? WHERE sku = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            for (Map.Entry<String, Integer> entry : skuQuantities.entrySet()) {
                pstmt.setInt(1, entry.getValue());
                pstmt.setString(2, entry.getKey());
                pstmt.executeUpdate();
            }
        }
    }

    private Product mapProduct(ResultSet rs) throws SQLException {
        return new Product(
            rs.getString("sku"),
            rs.getString("name"),
            rs.getBigDecimal("price"),
            rs.getBigDecimal("weight_kg"),
            rs.getInt("stock"),
            rs.getBoolean("discontinued")
        );
    }
}
package com.loja.repository;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.loja.domain.*;

import java.sql.*;
import java.time.Instant;
import java.util.*;

public class OrderRepository {
    private final Database database;
    private final ObjectMapper objectMapper;

    public OrderRepository(Database database, ObjectMapper objectMapper) {
        this.database = database;
        this.objectMapper = objectMapper;
    }

    public void save(Order order, Connection conn) throws SQLException {
        String sql = """
            INSERT INTO orders (id, customer_cpf, customer_email, zip_code, region, shipping_method,
                               coupon, payment_method, club_tier, status, created_at, tracking_code,
                               payment_transaction_id, summary_json)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?::json)
        """;

        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, order.getId());
            pstmt.setString(2, order.getCustomerCpf());
            pstmt.setString(3, order.getCustomerEmail());
            pstmt.setString(4, order.getZipCode());
            pstmt.setString(5, order.getRegion().name());
            pstmt.setString(6, order.getShippingMethod().name());
            pstmt.setString(7, order.getCoupon());
            pstmt.setString(8, order.getPaymentMethod().name());
            pstmt.setString(9, order.getClubTier().name());
            pstmt.setString(10, order.getStatus().name());
            pstmt.setTimestamp(11, Timestamp.from(order.getCreatedAt()));
            pstmt.setString(12, order.getTrackingCode());
            pstmt.setString(13, order.getPaymentTransactionId());
            pstmt.setString(14, objectMapper.writeValueAsString(order.getSummary()));
            pstmt.executeUpdate();
        } catch (JsonProcessingException e) {
            throw new SQLException("Failed to serialize summary", e);
        }

        String itemSql = "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)";
        try (PreparedStatement pstmt = conn.prepareStatement(itemSql)) {
            for (OrderItem item : order.getItems()) {
                pstmt.setString(1, order.getId());
                pstmt.setString(2, item.getSku());
                pstmt.setInt(3, item.getQuantity());
                pstmt.addBatch();
            }
            pstmt.executeBatch();
        }
    }

    public Optional<Order> findById(String id) {
        String sql = "SELECT * FROM orders WHERE id = ?";
        try (Connection conn = database.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    Order order = mapOrder(rs);
                    loadItems(order, conn);
                    return Optional.of(order);
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to find order", e);
        }
        return Optional.empty();
    }

    public Optional<Order> findByIdForUpdate(String id, Connection conn) throws SQLException {
        String sql = "SELECT * FROM orders WHERE id = ? FOR UPDATE";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    Order order = mapOrder(rs);
                    loadItems(order, conn);
                    return Optional.of(order);
                }
            }
        }
        return Optional.empty();
    }

    public void updateStatus(String orderId, OrderStatus status, Connection conn) throws SQLException {
        String sql = "UPDATE orders SET status = ? WHERE id = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, status.name());
            pstmt.setString(2, orderId);
            pstmt.executeUpdate();
        }
    }

    public void updateTrackingCode(String orderId, String trackingCode, Connection conn) throws SQLException {
        String sql = "UPDATE orders SET tracking_code = ? WHERE id = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, trackingCode);
            pstmt.setString(2, orderId);
            pstmt.executeUpdate();
        }
    }

    public void updatePaymentTransaction(String orderId, String transactionId, Connection conn) throws SQLException {
        String sql = "UPDATE orders SET payment_transaction_id = ? WHERE id = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, transactionId);
            pstmt.setString(2, orderId);
            pstmt.executeUpdate();
        }
    }

    public boolean hasCompletedOrders(String cpf, Connection conn) throws SQLException {
        String sql = "SELECT COUNT(*) FROM orders WHERE customer_cpf = ? AND status IN ('PAID', 'SHIPPED', 'DELIVERED')";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, cpf);
            try (ResultSet rs = pstmt.executeQuery()) {
                rs.next();
                return rs.getInt(1) > 0;
            }
        }
    }

    public boolean recordPaymentTransaction(String orderId, String transactionId, Instant paidAt, Connection conn) throws SQLException {
        String sql = "INSERT INTO payment_transactions (order_id, transaction_id, paid_at) VALUES (?, ?, ?) ON CONFLICT DO NOTHING";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, orderId);
            pstmt.setString(2, transactionId);
            pstmt.setTimestamp(3, Timestamp.from(paidAt));
            int inserted = pstmt.executeUpdate();
            return inserted > 0;
        }
    }

    private void loadItems(Order order, Connection conn) throws SQLException {
        String sql = "SELECT * FROM order_items WHERE order_id = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, order.getId());
            try (ResultSet rs = pstmt.executeQuery()) {
                List<OrderItem> items = new ArrayList<>();
                while (rs.next()) {
                    items.add(new OrderItem(
                        rs.getString("sku"),
                        rs.getInt("quantity")
                    ));
                }
                order.setItems(items);
            }
        }
    }

    private Order mapOrder(ResultSet rs) throws SQLException {
        Order order = new Order();
        order.setId(rs.getString("id"));
        order.setCustomerCpf(rs.getString("customer_cpf"));
        order.setCustomerEmail(rs.getString("customer_email"));
        order.setZipCode(rs.getString("zip_code"));
        order.setRegion(Region.valueOf(rs.getString("region")));
        order.setShippingMethod(ShippingMethod.valueOf(rs.getString("shipping_method")));
        order.setCoupon(rs.getString("coupon"));
        order.setPaymentMethod(PaymentMethod.valueOf(rs.getString("payment_method")));
        order.setClubTier(ClubTier.valueOf(rs.getString("club_tier")));
        order.setStatus(OrderStatus.valueOf(rs.getString("status")));
        order.setCreatedAt(rs.getTimestamp("created_at").toInstant());
        order.setTrackingCode(rs.getString("tracking_code"));
        order.setPaymentTransactionId(rs.getString("payment_transaction_id"));

        try {
            String summaryJson = rs.getString("summary_json");
            CheckoutSummary summary = objectMapper.readValue(summaryJson, CheckoutSummary.class);
            order.setSummary(summary);
        } catch (JsonProcessingException e) {
            throw new SQLException("Failed to deserialize summary", e);
        }

        return order;
    }
}
package com.loja.repository;

import com.loja.domain.Customer;

