        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
        if (discount.compareTo(maxDiscount) > 0) {
            return maxDiscount.setScale(2, java.math.RoundingMode.HALF_EVEN);
        }
        return discount;
    }
}
